import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const m=JSON.parse('{"title":"Trigger","description":"Die sechs Auslöser eines Flows in ApptiveGrid und wann welcher passt.","frontmatter":{"title":"Trigger","description":"Die sechs Auslöser eines Flows in ApptiveGrid und wann welcher passt."},"headers":[],"relativePath":"flows/trigger.md","filePath":"flows/trigger.md","lastUpdated":1786016533000}'),a={name:"flows/trigger.md"};function s(o,e,l,d,g,u){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ausloser" tabindex="-1">Auslöser <a class="header-anchor" href="#ausloser" aria-label="Permalink to &quot;Auslöser&quot;">​</a></h1><p>Der <strong>Auslöser</strong> ist das Ereignis, das einen Flow startet. Jeder Flow hat genau einen.</p><p>Im Editor liegen die Auslöser im Reiter <strong>Auslöser</strong> unter der Frage <em>Wann soll der Flow starten?</em>.</p><div class="warning custom-block"><p class="custom-block-title">Der Auslöser ist die wichtigste Entscheidung</p><p>Er bestimmt nicht nur <em>wann</em> der Flow läuft, sondern auch <em>welche Daten</em> allen folgenden Schritten zur Verfügung stehen. Ein nachträglicher Wechsel bedeutet meist, die folgenden Schritte neu zu konfigurieren.</p></div><h2 id="die-sechs-ausloser" tabindex="-1">Die sechs Auslöser <a class="header-anchor" href="#die-sechs-ausloser" aria-label="Permalink to &quot;Die sechs Auslöser&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Auslöser</th><th>Beschreibung in der Oberfläche</th></tr></thead><tbody><tr><td><strong>Neuer Eintrag</strong></td><td><em>Ein neuer Eintrag wurde hinzugefügt</em></td></tr><tr><td><strong>Eintrag wurde geändert</strong></td><td><em>Ein bestehender Eintrag wurde geändert</em></td></tr><tr><td><strong>Eintrag per Formular</strong></td><td><em>Neuer Eintrag per Formular hinzugefügt</em></td></tr><tr><td><strong>Eintrag per Formular geändert</strong></td><td><em>Bestehender Eintrag per Formular geändert</em></td></tr><tr><td><strong>Webhook</strong></td><td><em>Ausgelöst durch eine externe Anfrage</em></td></tr><tr><td><strong>Seite anzeigen</strong></td><td><em>Flow starten und Seite laden</em></td></tr></tbody></table><hr><h2 id="neuer-eintrag" tabindex="-1">Neuer Eintrag <a class="header-anchor" href="#neuer-eintrag" aria-label="Permalink to &quot;Neuer Eintrag&quot;">​</a></h2><p>Startet, sobald in einem Grid ein Eintrag entsteht — <strong>unabhängig davon, woher er kommt</strong>: aus der Tabelle, aus einem Formular, per CSV-Import oder über einen anderen Flow.</p><p><strong>Konfiguration:</strong> Grid auswählen.</p><p><strong>Geeignet für:</strong> alles, was bei jedem neuen Datensatz passieren soll, egal auf welchem Weg er entstanden ist.</p><div class="warning custom-block"><p class="custom-block-title">CSV-Import löst mit aus</p><p>Importieren Sie 500 Zeilen per CSV, entstehen 500 neue Einträge. Prüfen Sie vor einem größeren Import, ob ein Flow daran hängt — sonst gehen unbeabsichtigt 500 E-Mails raus.</p></div><hr><h2 id="eintrag-wurde-geandert" tabindex="-1">Eintrag wurde geändert <a class="header-anchor" href="#eintrag-wurde-geandert" aria-label="Permalink to &quot;Eintrag wurde geändert&quot;">​</a></h2><p>Startet, wenn ein bestehender Eintrag geändert wird.</p><p><strong>Konfiguration:</strong> Grid auswählen und optional eine <strong>Bedingung</strong> auf ein bestimmtes Feld.</p><div class="tip custom-block"><p class="custom-block-title">Immer eine Bedingung setzen</p><p>Ohne Bedingung startet der Flow bei <em>jeder</em> Änderung an <em>jedem</em> Feld — auch bei einer korrigierten Schreibweise im Namensfeld. Das erzeugt viele überflüssige Durchläufe.</p><p>Beschränken Sie den Auslöser auf das Feld, um das es wirklich geht — etwa <code>Status</code>.</p></div><h3 id="nicht-alle-felder-taugen-als-bedingung" tabindex="-1">Nicht alle Felder taugen als Bedingung <a class="header-anchor" href="#nicht-alle-felder-taugen-als-bedingung" aria-label="Permalink to &quot;Nicht alle Felder taugen als Bedingung&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feldtyp</th><th>Als Bedingung</th></tr></thead><tbody><tr><td>Text, Zahl, Datum, Auswahl, Währung, Häkchen, …</td><td>mit Wertvergleich</td></tr><tr><td>Dateien, Adresse, Geolokalisierung, Unterschrift, Erstellt von, Interne Verknüpfung</td><td>nur „hat sich geändert&quot;, ohne Wertvergleich</td></tr><tr><td><strong>Wert übernehmen</strong>, <strong>Summe berechnen</strong>, <strong>Formel</strong></td><td><strong>nicht wählbar</strong></td></tr><tr><td><strong>Erstellt am</strong></td><td><strong>nicht wählbar</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Berechnete Felder lösen nicht aus</p><p>Ändert sich ein Feld vom Typ <em>Wert übernehmen</em>, <em>Summe berechnen</em> oder <em>Formel</em>, lässt sich das nicht als Auslöser nutzen. Wollen Sie auf eine Berechnung reagieren, müssen Sie stattdessen auf das zugrunde liegende Feld reagieren.</p></div><hr><h2 id="eintrag-per-formular" tabindex="-1">Eintrag per Formular <a class="header-anchor" href="#eintrag-per-formular" aria-label="Permalink to &quot;Eintrag per Formular&quot;">​</a></h2><p>Startet, wenn ein bestimmtes <strong>Formular</strong> einen neuen Eintrag anlegt.</p><p><strong>Konfiguration:</strong> Grid und Formular auswählen.</p><p><strong>Unterschied zu „Neuer Eintrag&quot;:</strong> Dieser Auslöser reagiert <strong>nur</strong> auf das gewählte Formular, nicht auf Einträge aus anderen Quellen.</p><div class="tip custom-block"><p class="custom-block-title">Der übliche Auslöser für Anmeldungen</p><p>Für Bestätigungsmails, Benachrichtigungen und Genehmigungsprozesse ist das fast immer der richtige Auslöser. Er ist präziser als <em>Neuer Eintrag</em> und geht bei Importen oder manueller Pflege nicht versehentlich los.</p></div><hr><h2 id="eintrag-per-formular-geandert" tabindex="-1">Eintrag per Formular geändert <a class="header-anchor" href="#eintrag-per-formular-geandert" aria-label="Permalink to &quot;Eintrag per Formular geändert&quot;">​</a></h2><p>Wie oben, aber für Formulare, die einen <strong>bestehenden</strong> Eintrag bearbeiten.</p><p><strong>Geeignet für:</strong> Rückmeldungen auf einen <a href="/docs/formulare/vorausgefuellte-links">vorausgefüllten Formularlink</a> — etwa eine Zu- oder Absage.</p><hr><h2 id="webhook" tabindex="-1">Webhook <a class="header-anchor" href="#webhook" aria-label="Permalink to &quot;Webhook&quot;">​</a></h2><p>Startet, wenn ein fremdes System eine Anfrage schickt. Damit binden Sie ApptiveGrid an beliebige andere Werkzeuge an.</p><p>Die Konfiguration erklärt sich in der Oberfläche selbst unter <em>Link zum Starten des Flows</em>:</p><blockquote><p><em>Um den Flow zu starten, senden Sie eine POST-Request an die folgende URL:</em></p></blockquote><p><strong>POST-Request senden</strong></p><blockquote><p><em>Senden Sie Daten im JSON-Format per POST-Request an den obigen Link, um den Flow zu starten.</em></p></blockquote><p><strong>Als Webhook verwenden</strong></p><blockquote><p><em>Tragen Sie die URL als Webhook bei anderen Services ein. Dadurch wird der Workflow automatisch gestartet, wenn der entsprechende Service den Webhook auslöst.</em></p></blockquote><p><strong>Webhook testen</strong></p><blockquote><p><em>Sie können den Webhook testen, indem Sie einen Beispiel-JSON-Payload senden:</em></p></blockquote><p>Dafür gibt es ein Eingabefeld <em>JSON-Payload</em> und die Schaltfläche <strong>Jetzt testen</strong>.</p><div class="danger custom-block"><p class="custom-block-title">Die Webhook-URL ist ein Zugang</p><p>Wer die URL kennt, kann den Flow starten. Behandeln Sie sie wie ein Passwort: nicht in öffentliche Repositories, nicht in Chats, nicht auf Folien.</p><p>Alle aktiven Zugänge eines Space sehen Sie unter <a href="/docs/zusammenarbeit/externe-links">Externe Links im Überblick</a>.</p></div><p>→ <a href="/docs/flows/webhook-trigger">Flow per Webhook starten</a></p><hr><h2 id="seite-anzeigen" tabindex="-1">Seite anzeigen <a class="header-anchor" href="#seite-anzeigen" aria-label="Permalink to &quot;Seite anzeigen&quot;">​</a></h2><p>Startet, wenn eine <strong>Seite</strong> geöffnet und abgesendet wird. Damit beginnt ein Flow mit einer Benutzeroberfläche statt mit einem Datenereignis.</p><p>Die Oberfläche erklärt:</p><blockquote><p><em>Verwende den unten stehenden Link, um die erste Seite unseres Flows zu öffnen. Sobald diese Seite abgesendet wurde, wird der Flow gestartet.</em></p></blockquote><p>Und zur Verteilung:</p><blockquote><p><em>Du kannst diesen Link auch weitergeben, zum Beispiel als QR-Code für einfachen Zugriff oder auf Ihrer Webseite oder im Intranet verlinken.</em></p></blockquote><p><strong>Geeignet für:</strong> geführte Prozesse, bei denen zu Beginn eine Eingabemaske steht — Störungsmeldungen, Bestellungen, mehrstufige Anträge.</p><div class="warning custom-block"><p class="custom-block-title">Zwei Schritte heißen „Seite anzeigen&quot;</p><p>Der <strong>Auslöser</strong> <em>Seite anzeigen</em> startet einen Flow mit einer Seite. Die <strong>Aktion</strong> <em>Seite anzeigen</em> zeigt mitten im Flow eine Seite an.</p><p>Beide tragen in der Oberfläche denselben Namen. Achten Sie darauf, in welchem Reiter Sie sich befinden: <em>Auslöser</em> oder <em>Aktionen</em>.</p></div><hr><h2 id="welcher-ausloser-passt" tabindex="-1">Welcher Auslöser passt? <a class="header-anchor" href="#welcher-ausloser-passt" aria-label="Permalink to &quot;Welcher Auslöser passt?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ziel</th><th>Auslöser</th></tr></thead><tbody><tr><td>Reagieren auf Anmeldungen über ein bestimmtes Formular</td><td><strong>Eintrag per Formular</strong></td></tr><tr><td>Reagieren auf jeden neuen Datensatz, egal woher</td><td><strong>Neuer Eintrag</strong></td></tr><tr><td>Reagieren auf einen Statuswechsel</td><td><strong>Eintrag wurde geändert</strong> mit Bedingung</td></tr><tr><td>Anbindung an ein fremdes System</td><td><strong>Webhook</strong></td></tr><tr><td>Prozess mit Eingabemaske am Anfang</td><td><strong>Seite anzeigen</strong></td></tr><tr><td>Rückmeldung auf einen verschickten Link</td><td><strong>Eintrag per Formular geändert</strong></td></tr></tbody></table><h2 id="veraltete-ausloser" tabindex="-1">Veraltete Auslöser <a class="header-anchor" href="#veraltete-ausloser" aria-label="Permalink to &quot;Veraltete Auslöser&quot;">​</a></h2><p>In älteren Flows können Auslöser auftauchen, die im Editor als <strong>veraltet</strong> gekennzeichnet sind. Sie funktionieren weiter, sollten bei einer Überarbeitung aber durch die aktuellen Varianten ersetzt werden.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/flows/aktionen">Aktionen</a></li><li><a href="/docs/flows/daten-zwischen-schritten">Daten zwischen Schritten</a></li><li><a href="/docs/flows/testen">Flows testen</a></li></ul>',60)])])}const c=t(a,[["render",s]]);export{m as __pageData,c as default};
